interface ProposalRequest {
  requestId: string;
  customerIds: string[];
  requestedAt: string;
}

interface AcceptedApproval {
  commandId: string;
  state: 'accepted';
}

interface CancelExecutionRequest {
  cancelCommandId: string;
  executionCommandId: string;
}

interface CancelReceipt {
  cancelCommandId: string;
  state: 'requested' | 'rejected' | 'too-late';
}

interface RollbackCommand {
  rollbackCommandId: string;
  executionCommandId: string;
  items: Array<{
    customerId: string;
    rollbackToken: string;
    expectedCustomerVersion: number;
  }>;
}

interface BulkEditReviewClient {
  requestProposal(input: ProposalRequest, signal: AbortSignal): Promise<GeneratedProposalContent>;
  getProposalEnvelope(proposalId: string, signal: AbortSignal): Promise<ProposalEnvelope>;
  approve(input: ApprovalCommand, signal: AbortSignal): Promise<AcceptedApproval>;
  requestCancel(input: CancelExecutionRequest, signal: AbortSignal): Promise<CancelReceipt>;
  getActionOutcome(commandId: string, signal: AbortSignal): Promise<ActionOutcome>;
  rollback(input: RollbackCommand, signal: AbortSignal): Promise<ActionOutcome>;
}
